def _v4_model_forward(model, xt: torch.Tensor):
    """Forward v4 model; retry without cuDNN RNN on long / awkward tensors."""
    try:
        return model(xt)
    except RuntimeError as exc:
        msg = str(exc)
        if "cuDNN" not in msg and "CUDNN" not in msg:
            raise
        with torch.backends.cudnn.flags(enabled=False):
            return model(xt)

