def logsumexp_np(a: np.ndarray, axis: int) -> np.ndarray:
    m = np.max(a, axis=axis, keepdims=True)
    with np.errstate(under="ignore", invalid="ignore"):
        out = m + np.log(np.sum(np.exp(a - m), axis=axis, keepdims=True))
    return np.squeeze(out, axis=axis)


def state_posteriors(
    log_emit: np.ndarray,
    log_trans: np.ndarray,
    log_init: np.ndarray | None = None,
) -> np.ndarray:
    """Forward-backward state marginals, returned as ``(L, S)`` probabilities."""
    le = np.asarray(log_emit, dtype=np.float64)
    tr = np.asarray(log_trans, dtype=np.float64)
    L, S = le.shape
    if log_init is None:
        log_init = np.full((S,), -1e30, dtype=np.float64)
        log_init[0] = 0.0
    else:
        log_init = np.asarray(log_init, dtype=np.float64)

    log_alpha = np.empty((L, S), dtype=np.float64)
    log_beta = np.empty((L, S), dtype=np.float64)
    log_alpha[0] = log_init + le[0]
    for t in range(1, L):
        log_alpha[t] = logsumexp_np(log_alpha[t - 1][:, None] + tr, axis=0) + le[t]

    log_beta[-1] = 0.0
    for t in range(L - 2, -1, -1):
        log_beta[t] = logsumexp_np(tr + le[t + 1][None, :] + log_beta[t + 1][None, :], axis=1)

    log_z = logsumexp_np(log_alpha[-1], axis=0)
    gamma_log = log_alpha + log_beta - log_z
    gamma = np.exp(np.clip(gamma_log, -80.0, 0.0)).astype(np.float32)
    gamma /= gamma.sum(axis=1, keepdims=True).clip(min=1e-12)
    return gamma


def state_to_channel_posterior(state_post: np.ndarray, state_to_channel: np.ndarray, n_channels: int = 11) -> np.ndarray:
    out = np.zeros((state_post.shape[0], n_channels), dtype=np.float32)
    for state, channel in enumerate(state_to_channel):
        out[:, int(channel)] += state_post[:, state]
    out /= out.sum(axis=1, keepdims=True).clip(min=1e-12)
    return out


def state_to_channel_posterior_torch(
    state_post: torch.Tensor,
    state_to_channel: torch.Tensor,
    n_channels: int = 11,
) -> torch.Tensor:
    """Collapse HMM state posteriors to CNN channels.

    Shapes: ``state_post`` is ``(B, L, S)`` and ``state_to_channel`` is ``(S,)``.
    Returns ``(B, L, n_channels)`` with rows normalized to sum to one.
    """
    if state_post.dim() != 3:
        raise ValueError(f"state_post must be (B,L,S), got {tuple(state_post.shape)}")
    idx = state_to_channel.to(device=state_post.device, dtype=torch.long)
    out = torch.zeros(
        (*state_post.shape[:2], n_channels),
        device=state_post.device,
        dtype=state_post.dtype,
    )
    out.scatter_add_(-1, idx.view(1, 1, -1).expand_as(state_post), state_post)
    return out / out.sum(dim=-1, keepdim=True).clamp_min(1e-12)


def joint_hmm_channel_posterior_torch(
    hmm: ProkaryoticJointHMM,
    probs_11: torch.Tensor,
    triplet_plus: torch.Tensor,
    triplet_minus: torch.Tensor,
    *,
    init_mode: str = "strict",
) -> Tuple[torch.Tensor, torch.Tensor]:
    """Differentiable Strategy-B posterior collapsed to 11 CNN channels.

    Shapes: ``probs_11`` is ``(B, L, 11)``, triplets are ``(B, L)``. Returns
    ``(posterior_11, nll_per_base)`` where posterior rows sum to one.
    """
    log_emit = hmm.log_emission(probs_11, triplet_plus.long(), triplet_minus.long())
    gamma, log_z, _log_alpha, _log_beta = hmm.forward_backward(log_emit, init_mode=init_mode)
    post = state_to_channel_posterior_torch(
        gamma,
        get_joint_state_to_channel_torch(),
        n_channels=11,
    )
    return post, -log_z / probs_11.shape[1]


def strand_hmm_channel_posterior_torch(
    hmm_plus: ProkaryoticStrandHMM,
    hmm_minus: ProkaryoticStrandHMM,
    probs_11: torch.Tensor,
    triplet_plus: torch.Tensor,
    triplet_minus_rc: torch.Tensor,
    *,
    init_mode: str = "strict",
) -> Tuple[torch.Tensor, torch.Tensor]:
    """Differentiable Strategy-A posterior from two independent strand HMMs.

    Shapes: ``probs_11`` is ``(B, L, 11)``, ``triplet_plus`` and
    ``triplet_minus_rc`` are ``(B, L)``. The minus branch is run on reversed
    genomic windows, then flipped back before merging to 11 channels.
    """
    probs_plus = probs_11[..., [0, 1, 2, 3, 7, 9]]
    log_emit_p = hmm_plus.log_emission(probs_plus, triplet_plus.long())
    gamma_p, log_z_p, _la_p, _lb_p = hmm_plus.forward_backward(log_emit_p, init_mode=init_mode)

    # Match run_viterbi_annotation.reverse_for_minus_strand(slice_minus_channels(...)):
    # reverse time and swap F0/F2 so the RC-oriented strand HMM sees
    # [IGR, CDS0, CDS1, CDS2, START, STOP] in its own coordinate system.
    probs_minus_rc = probs_11.flip(dims=[1])[..., [0, 6, 5, 4, 8, 10]]
    log_emit_m = hmm_minus.log_emission(probs_minus_rc, triplet_minus_rc.long())
    gamma_m_rc, log_z_m, _la_m, _lb_m = hmm_minus.forward_backward(log_emit_m, init_mode=init_mode)
    gamma_m = gamma_m_rc.flip(dims=[1])

    out = torch.zeros(
        (*probs_11.shape[:2], 11),
        device=probs_11.device,
        dtype=probs_11.dtype,
    )
    out[..., 0] = gamma_p[..., 0] * gamma_m[..., 0]
    edge = strand_hmm_nn_channels()[2] != 4
    plus_map_list = (
        [0, 7, 2, 3, 1, 2, 3, 1, 2, 9, 7, 7]
        if edge else [0, 7, 7, 7, 1, 2, 3, 9, 9, 9, 7, 7]
    )
    minus_map_list = (
        [0, 8, 5, 6, 6, 5, 4, 4, 5, 10, 8, 8]
        if edge else [0, 8, 8, 8, 6, 5, 4, 10, 10, 10, 8, 8]
    )
    plus_channel = torch.tensor(
        plus_map_list[: hmm_plus.NUM_STATES],
        device=probs_11.device,
        dtype=torch.long,
    )
    minus_channel = torch.tensor(
        minus_map_list[: hmm_minus.NUM_STATES],
        device=probs_11.device,
        dtype=torch.long,
    )
    for state in range(1, hmm_plus.NUM_STATES):
        out[..., int(plus_channel[state])] += gamma_p[..., state]
    for state in range(1, hmm_minus.NUM_STATES):
        out[..., int(minus_channel[state])] += gamma_m[..., state]
    out = out / out.sum(dim=-1, keepdim=True).clamp_min(1e-12)
    return out, -(log_z_p + log_z_m) / (2.0 * probs_11.shape[1])


def joint_hmm_channel_posterior(
    probs_11: np.ndarray,
    seq: str,
    stats: Dict,
    alpha: float = 0.001,
) -> np.ndarray:
    """Strategy-B HMM posterior mapped from 19 states onto the 11 CNN channels."""
    hmm = ProkaryoticJointHMM(stats, alpha=alpha, trainable=False)
    tp, tm = encode_triplets(seq)
    log_emit = hmm.log_emission(
        torch.from_numpy(probs_11).float(),
        torch.from_numpy(tp).long(),
        torch.from_numpy(tm).long(),
    ).detach().cpu().numpy()
    gamma = state_posteriors(
        log_emit,
        hmm.log_transitions().detach().cpu().numpy(),
        hmm.log_init().detach().cpu().numpy(),
    )
    return state_to_channel_posterior(gamma, get_joint_state_to_channel(), n_channels=11)


def strand_hmm_channel_posterior(
    probs_11: np.ndarray,
    seq: str,
    stats: Dict,
    alpha: float = 0.001,
) -> np.ndarray:
    """Strategy-A independent strand posteriors mapped to merged 11-channel targets.

    This target is multi-label-like: plus and minus coding labels can both be high.
    The IGR channel is approximated as P(+ IGR) * P(- IGR).
    """
    out = np.zeros((len(seq), 11), dtype=np.float32)

    hmm_p = ProkaryoticStrandHMM(stats, alpha=alpha, trainable=False)
    triplet_p, _ = encode_triplets(seq)
    log_emit_p = hmm_p.log_emission(
        torch.from_numpy(slice_plus_channels(probs_11)).float(),
        torch.from_numpy(triplet_p).long(),
    ).detach().cpu().numpy()
    gamma_p = state_posteriors(
        log_emit_p,
        hmm_p.log_transitions().detach().cpu().numpy(),
        hmm_p.log_init().detach().cpu().numpy(),
    )

    hmm_m = ProkaryoticStrandHMM(stats, alpha=alpha, trainable=False)
    rc = reverse_complement_dna(seq)
    triplet_m, _ = encode_triplets(rc)
    log_emit_m = hmm_m.log_emission(
        torch.from_numpy(reverse_for_minus_strand(slice_minus_channels(probs_11))).float(),
        torch.from_numpy(triplet_m).long(),
    ).detach().cpu().numpy()
    gamma_m = state_posteriors(
        log_emit_m,
        hmm_m.log_transitions().detach().cpu().numpy(),
        hmm_m.log_init().detach().cpu().numpy(),
    )[::-1].copy()

    out[:, 0] = gamma_p[:, 0] * gamma_m[:, 0]
    edge = strand_hmm_nn_channels()[2] != 4
    plus_map = (
        (0, 7, 2, 3, 1, 2, 3, 1, 2, 9, 7, 7)
        if edge else (0, 7, 7, 7, 1, 2, 3, 9, 9, 9, 7, 7)
    )
    minus_map = (
        (0, 8, 5, 6, 6, 5, 4, 4, 5, 10, 8, 8)
        if edge else (0, 8, 8, 8, 6, 5, 4, 10, 10, 10, 8, 8)
    )
    for state in range(1, hmm_p.NUM_STATES):
        out[:, plus_map[state]] += gamma_p[:, state]
    for state in range(1, hmm_m.NUM_STATES):
        out[:, minus_map[state]] += gamma_m[:, state]
    return out


def sigmoid_probs_to_softmax(probs_11: np.ndarray, eps: float = 1e-6) -> np.ndarray:
    """Convert cached sigmoid probabilities back to logits, then softmax them."""
    p = np.clip(probs_11.astype(np.float64), eps, 1.0 - eps)
    logits = np.log(p) - np.log1p(-p)
    logits -= logits.max(axis=1, keepdims=True)
    sm = np.exp(logits)
    sm /= sm.sum(axis=1, keepdims=True).clip(min=eps)
    return sm.astype(np.float32)


def v4_conv_receptive_field(
    *,
    numb_conv: int = 3,
    kernel_size: int = 9,
    initial_kernel_size: int = 3,
    cnn_stride: int = 1,
    enable_dilated_stem: bool = False,
    dilated_dilations: Tuple[int, ...] = (1, 3, 9),
) -> int:
    """1D receptive field at each BiLSTM step (CNN stem + optional stride-3 downsample)."""
    rf = initial_kernel_size
    if enable_dilated_stem:
        max_d = max(int(d) for d in dilated_dilations) if dilated_dilations else 1
        rf += (3 - 1) * max_d
    for _ in range(max(0, numb_conv - 1)):
        rf += kernel_size - 1
    if cnn_stride > 1:
        rf = rf + (cnn_stride - 1) * (rf - 1)
    return rf


def _window_starts(l_pad: int, window: int, step: int, phase: int = 1) -> list[int]:
    """Tile starts. ``phase`` > 1 keeps every start a multiple of ``phase`` (the model's
    triplet pooling counts from the tile's first base, so phase-aligned tiles see the
    same codon grouping as a whole-contig pass); the last tile then ends at or just
    before the contig end instead of exactly at it."""
    starts = list(range(0, max(1, l_pad - window + 1), step))
    if not starts or starts[-1] + window < l_pad:
        last = max(0, l_pad - window)
        if phase > 1:
            last -= last % phase
        starts.append(last)
    return starts


def _normalize_stitched(out: np.ndarray, activation: str) -> np.ndarray:
    if activation == "softmax":
        out = out / out.sum(axis=1, keepdims=True).clip(min=1e-12)
    return out


@torch.no_grad()
def tile_predict_v4_distribution(
    model,
    oh_fwd_6: np.ndarray,
    window: int,
    step: int,
    device: torch.device,
    batch_size: int = 4,
    *,
    full_sequence: bool = False,
    activation: str = "softmax",
    stitch_mode: str = "mean",
    conv_margin: int | None = None,
    numb_conv: int = 3,
    cnn_stride: int = 1,
    sd_channel: bool = False,
    phase_channel: bool = False,
) -> np.ndarray:
    """v4 tiled/full-contig inference with selectable output distribution.

    ``activation='softmax'`` is intended for Tiberius-style categorical CNNs.
    ``activation='sigmoid'`` matches the older multi-label v4 pipeline.

    ``stitch_mode`` controls overlapping-window merge:

    * ``mean`` — average (legacy default).
    * ``center`` — per base, keep the tile where that base is farthest from the
      window edge (minus ``conv_margin`` ≈ half the CNN receptive field).
    * ``min`` / ``max`` — element-wise min/max across tiles.
    """
    if window <= 0:
        raise ValueError(f"window must be positive, got {window}")
    if step <= 0:
        raise ValueError(f"step must be positive, got {step}")
        raise ValueError(f"unknown activation: {activation}")
    if stitch_mode not in {"mean", "center", "min", "max"}:
        raise ValueError(f"unknown stitch_mode: {stitch_mode}")

    x_full = merge_strand_features(
        oh_fwd_6, sd_channel=sd_channel, phase_channel=phase_channel,
    )
    if x_full.ndim != 2:
        raise ValueError(f"expected merged features to be 2D, got {x_full.shape}")
    if x_full.shape[1] not in VALID_V4_INP_SIZES and x_full.shape[0] in VALID_V4_INP_SIZES:
        x_full = x_full.T.copy()
    expected_in = v4_input_size(sd_channel=sd_channel, phase_channel=phase_channel)
    if x_full.shape[1] != expected_in:
        raise ValueError(f"expected merged features (L,{expected_in}), got {x_full.shape}")
    l_orig = x_full.shape[0]
    pool = model.pool_size
    if full_sequence and l_orig < window:
        print(
            f"note: contig len {l_orig:,} < window {window:,}; "
            f"using sliding-window NN inference",
            flush=True,
        )
        full_sequence = False
    if full_sequence:
        pad_len = (pool - (l_orig % pool)) % pool
        if pad_len:
            x_full = np.pad(x_full, ((0, pad_len), (0, 0)), mode="constant")
        l_pad = x_full.shape[0]
        window = l_pad
        step = l_pad
    else:
        l_pad = l_orig

    n_classes = model.output_size
    # "center" stitching is the full-contig-equivalent mode: phase-align every tile.
    starts = _window_starts(l_pad, window, step, phase=pool if stitch_mode == "center" else 1)
    if stitch_mode == "center" and (starts[-1] + window < l_pad):
        starts.append(starts[-1] + pool * ((l_pad - window - starts[-1] + pool - 1) // pool))
    if conv_margin is None:
        conv_margin = v4_conv_receptive_field(
            numb_conv=numb_conv,
            cnn_stride=cnn_stride,
            enable_dilated_stem=bool(getattr(model, "enable_dilated_stem", False)),
            dilated_dilations=tuple(getattr(model, "dilated_dilations", (1, 3, 9))),
        ) // 2

    prob_sum = np.zeros((l_pad, n_classes), dtype=np.float32)
    counts = np.zeros(l_pad, dtype=np.float32)
    if stitch_mode == "center":
        best_score = np.full(l_pad, -1e9, dtype=np.float32)
        best_probs = np.zeros((l_pad, n_classes), dtype=np.float32)
        filled = np.zeros(l_pad, dtype=bool)
    elif stitch_mode in {"min", "max"}:
        best_probs = (
            np.ones((l_pad, n_classes), dtype=np.float32)
            if stitch_mode == "min"
            else np.zeros((l_pad, n_classes), dtype=np.float32)
        )
        filled = np.zeros(l_pad, dtype=bool)

    model.eval()
    win_end = window - 1
    n_batches = (len(starts) + batch_size - 1) // batch_size
    tiling = (
        "in one pass (no tiling)" if full_sequence
        else f"in {len(starts)} tiles of {window:,} nt (step {step:,})"
    )
    print(
        f"    scoring {l_orig:,} bp {tiling}, "
        f"{n_batches} batches of {batch_size}, device {device}",
        flush=True,
    )
    for i in range(0, len(starts), batch_size):
        batch_starts = starts[i:i + batch_size]
        chunks = []
        for start in batch_starts:
            chunk = x_full[start:start + window]
            if chunk.shape[0] < window:
                chunk = np.pad(chunk, ((0, window - chunk.shape[0]), (0, 0)))
            chunks.append(chunk)
        xt = torch.from_numpy(np.stack(chunks).astype(np.float32)).to(device)
        if i == 0 or (i // batch_size) % 50 == 0:
            print(
                f"      batch {i // batch_size + 1}/{n_batches}, "
                f"positions {batch_starts[0]:,}-{batch_starts[-1]:,}",
                flush=True,
            )
        out = _v4_model_forward(model, xt)
        logits = out[0] if isinstance(out, tuple) else out
        if activation == "softmax":
            probs = torch.softmax(logits, dim=-1).cpu().numpy()
        else:
            probs = torch.sigmoid(logits).cpu().numpy()
        for b, start in enumerate(batch_starts):
            seg = probs[b]
            end = min(start + seg.shape[0], l_pad)
            seg_len = end - start
            seg = seg[:seg_len]
            if stitch_mode == "mean":
                prob_sum[start:end] += seg.astype(np.float32, copy=False)
                counts[start:end] += 1.0
            elif stitch_mode == "center":
                j = np.arange(seg_len)
                score = (np.minimum(j, win_end - j) - conv_margin).astype(np.float32)
                better = score > best_score[start:end]
                best_score[start:end][better] = score[better]
                best_probs[start:end][better] = seg[better]
                filled[start:end] |= better
                prob_sum[start:end] += seg.astype(np.float32, copy=False)
                counts[start:end] += 1.0
            else:
                for j in range(seg_len):
                    pos = start + j
                    prob_sum[pos] += seg[j]
                    counts[pos] += 1.0
                    if stitch_mode == "center":
                        edge_dist = min(pos - start, win_end - (pos - start))
                        score = float(edge_dist - conv_margin)
                        if score > best_score[pos]:
                            best_score[pos] = score
                            best_probs[pos] = seg[j]
                            filled[pos] = True
                    elif stitch_mode == "min":
                        if not filled[pos]:
                            best_probs[pos] = seg[j]
                            filled[pos] = True
                        else:
                            best_probs[pos] = np.minimum(best_probs[pos], seg[j])
                    else:
                        if not filled[pos]:
                            best_probs[pos] = seg[j]
                            filled[pos] = True
                        else:
                            best_probs[pos] = np.maximum(best_probs[pos], seg[j])

    if stitch_mode == "mean":
        out = prob_sum / np.maximum(counts, 1.0)[:, None]
    else:
        fallback = prob_sum / np.maximum(counts, 1.0)[:, None]
        out = np.where(filled[:, None], best_probs, fallback)

    return _normalize_stitched(out.astype(np.float32, copy=False), activation)[:l_orig]
